#!/usr/bin/env node
// Extract loaded memory values from an ELF binary.
// Usage: node extract.js /path/to/a.out > out.json
// Output: JSON object mapping each 4-byte-aligned memory (virtual) address
// to the little/native-endian 32-bit integer stored there, for every word
// that is fully backed by file content of a PT_LOAD segment.

const fs = require('fs');

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write('usage: node extract.js <elf>\n');
    process.exit(1);
  }
  const buf = fs.readFileSync(path);

  // ELF identification
  if (buf.length < 16 ||
      buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    process.stderr.write('not an ELF file\n');
    process.exit(1);
  }
  const is64 = buf[4] === 2;            // EI_CLASS: 1=32bit, 2=64bit
  const little = buf[5] === 1;          // EI_DATA: 1=LE, 2=BE

  const rU16 = (o) => little ? buf.readUInt16LE(o) : buf.readUInt16BE(o);
  const rU32 = (o) => little ? buf.readUInt32LE(o) : buf.readUInt32BE(o);
  const rU64 = (o) => {
    // return as Number (safe for file sizes / addresses in practice)
    const lo = little ? buf.readUInt32LE(o)     : buf.readUInt32BE(o + 4);
    const hi = little ? buf.readUInt32LE(o + 4) : buf.readUInt32BE(o);
    return hi * 0x100000000 + lo;
  };

  let e_phoff, e_phentsize, e_phnum;
  if (is64) {
    e_phoff = rU64(0x20);
    e_phentsize = rU16(0x36);
    e_phnum = rU16(0x38);
  } else {
    e_phoff = rU32(0x1c);
    e_phentsize = rU16(0x2a);
    e_phnum = rU16(0x2c);
  }

  const PT_LOAD = 1;
  const out = Object.create(null);

  for (let i = 0; i < e_phnum; i++) {
    const ph = e_phoff + i * e_phentsize;
    if (ph + e_phentsize > buf.length) break;
    const p_type = rU32(ph);
    if (p_type !== PT_LOAD) continue;

    let p_offset, p_vaddr, p_filesz;
    if (is64) {
      p_offset = rU64(ph + 0x08);
      p_vaddr = rU64(ph + 0x10);
      p_filesz = rU64(ph + 0x20);
    } else {
      p_offset = rU32(ph + 0x04);
      p_vaddr = rU32(ph + 0x08);
      p_filesz = rU32(ph + 0x10);
    }

    // Emit every 4-byte word fully backed by file content of this segment.
    for (let off = 0; off + 4 <= p_filesz; off += 4) {
      const foff = p_offset + off;
      if (foff + 4 > buf.length) break;
      const addr = p_vaddr + off;
      const val = little ? buf.readUInt32LE(foff) : buf.readUInt32BE(foff);
      out[String(addr)] = val;
    }
  }

  process.stdout.write(JSON.stringify(out));
}

main();

